def max_value_on_paths(N: int, grid_values: list) -> int:
    # Build grid with 1-indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # dp[i1][i2] = max sum when both walkers have taken k steps and are at (i1, j1) and (i2, j2)
    # where j1 = k - i1, j2 = k - i2
    NEG = -10**9
    dp = [[NEG] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]  # both start at (1,1), count once

    for k in range(2, 2 * N + 1):
        dp_next = [[NEG] * (N + 1) for _ in range(N + 1)]
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                best = NEG
                # iterate over previous positions
                for di1 in (0, 1):  # 0: came from left (i1), 1: came from up (i1-1)
                    pi1 = i1 - di1
                    pj1 = j1 - (1 - di1)
                    if pi1 < 1 or pj1 < 1 or pi1 > N or pj1 > N:
                        continue
                    for di2 in (0, 1):
                        pi2 = i2 - di2
                        pj2 = j2 - (1 - di2)
                        if pi2 < 1 or pj2 < 1 or pi2 > N or pj2 > N:
                            continue
                        prev = dp[pi1][pi2]
                        if prev == NEG:
                            continue
                        best = max(best, prev)
                if best == NEG:
                    continue
                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                dp_next[i1][i2] = best + add
        dp = dp_next

    return dp[N][N] if dp[N][N] != NEG else 0

