def verify_isbn(isbn: str) -> str:
    # Extract the 10 characters that are digits or 'X'
    digits = []
    for ch in isbn:
        if ch.isdigit():
            digits.append(int(ch))
        elif ch == 'X':
            digits.append(10)
    if len(digits) != 10:
        # Invalid format, but we will still try to correct
        return isbn
    # Compute checksum
    total = sum((i + 1) * digits[i] for i in range(10))
    if total % 11 == 0:
        return "Right"
    # Compute correct checksum digit
    sum9 = sum((i + 1) * digits[i] for i in range(9))
    correct_digit = sum9 % 11
    # Build corrected ISBN string
    parts = isbn.split('-')
    parts[-1] = str(correct_digit) if correct_digit < 10 else 'X'
    return '-'.join(parts)

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        degree = n - i
        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)
        # Determine coefficient part
        if abs_coeff == 1 and degree > 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)
        # Determine variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''
        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)
    if not terms:
        return '0'
    return ''.join(terms)

def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    if m <= 0:
        return (0, [])
    cutoff_count = int(1.5 * m)
    if cutoff_count > n:
        cutoff_count = n
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))
    if cutoff_count == 0:
        cutoff = 0
    else:
        cutoff = sorted_applicants[cutoff_count - 1][1]
    qualified = [app for app in sorted_applicants if app[1] >= cutoff]
    return (cutoff, qualified)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic length check
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    # Ensure mapping covers all 26 letters and is bijective
    if len(mapping) != 26:
        return "Failed"
    if len(set(mapping.values())) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def count_coprime_pairs(x0: int, y0: int) -> int:
    # If y0 is not a multiple of x0, no such pairs exist
    if y0 % x0 != 0:
        return 0
    n = y0 // x0

    # Helper function to compute gcd
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            a = i
            b = n // i
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        i += 1
    return count

def string_transformation(A: str, B: str, rules: list) -> int | str:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns minimum steps if possible, otherwise "NO ANSWER!".
    """
    if A == B:
        return 0
    from collections import deque
    queue = deque()
    queue.append((A, 0))
    visited = {A}
    max_steps = 10
    while queue:
        current, steps = queue.popleft()
        if steps >= max_steps:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1
    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    """Return True if num is a prime number, else False."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    # Build adjacency list for digit transformations
    adjacency = {}
    for x, y in rules:
        adjacency.setdefault(x, []).append(y)

    # Compute reachable digits for each digit 0-9
    reachable = {}
    for d in range(10):
        visited = {d}
        stack = [d]
        while stack:
            cur = stack.pop()
            for nxt in adjacency.get(cur, []):
                if nxt not in visited:
                    visited.add(nxt)
                    stack.append(nxt)
        reachable[d] = visited

    # Count unique numbers by multiplying reachable options per position
    product = 1
    for ch in str(n):
        d = int(ch)
        product *= len(reachable[d])
    return product

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Normalize names to upper case for comparison
    scenario_upper = scenario.upper()
    days_lower = {day.lower() for day in days_of_week}

    def is_statement_about_day(statement: str) -> bool:
        """Return True if the statement contains any day of the week."""
        stmt_lower = statement.lower()
        return any(day in stmt_lower for day in days_lower)

    def evaluate_statement(statement: str, speaker: str) -> bool:
        """Return True if the statement is true under the given scenario, False otherwise."""
        stmt = statement.strip().lower().rstrip('.')
        # Handle "I am guilty." / "I am not guilty."
        if stmt == "i am guilty":
            return speaker.upper() == scenario_upper
        if stmt == "i am not guilty":
            return speaker.upper() != scenario_upper
        # Handle "X is guilty." / "X is not guilty."
        if stmt.endswith("is guilty"):
            name = stmt[:-len("is guilty")].strip()
            return name.upper() == scenario_upper
        if stmt.endswith("is not guilty"):
            name = stmt[:-len("is not guilty")].strip()
            return name.upper() != scenario_upper
        # If statement format is unknown, treat it as neutral (does not affect consistency)
        return True

    for speaker, stmts in statements.items():
        for stmt in stmts:
            if is_statement_about_day(stmt):
                continue  # ignore day-of-week statements
            truth = evaluate_statement(stmt, speaker)
            if speaker in liar_count:
                if truth:
                    return False  # liar said a true statement
            else:
                if not truth:
                    return False  # truth-teller said a false statement
    return True

