def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    if m < 0:
        return 0
    if sum(a) < m:
        return 0
    dp = [0] * (m + 1)
    dp[0] = 1
    for limit in a:
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for k in range(1, m + 1):
            prefix[k] = (prefix[k - 1] + dp[k]) % MOD
        newdp = [0] * (m + 1)
        for k in range(m + 1):
            low = k - limit
            if low <= 0:
                newdp[k] = prefix[k]
            else:
                newdp[k] = (prefix[k] - prefix[low - 1]) % MOD
        dp = newdp
    return dp[m] % MOD

